#!/usr/bin/env python# -*- coding: utf-8 -*-"""Corrected Stage-E Target Mesh Generator and Input Deck BuilderStrictly matches the validated continuous Stage-D target deck architecture (1390447.mmaster02):- Two-layer UEL formulation: JTYPE=1 on DOF 3 (Phase) and JTYPE=2 on DOFs 1,2 (Mechanical)- Properties vector: (l0=0.015, Gc=0.0027, E=210.0, nu=0.3, k_tol=1e-7, N_PHYS, EXEC_MODE=0.0)- Top *EQUATION: Only shear DOF 1 coupled to RP 99999, top DOF 2 free- Step definition: Exact validated *STATIC 0.001, 1.0, 1.0e-9, 0.02 without erroneous CONTROLS multipliers- Fail-safe PBS script: Captures and propagates actual Abaqus exit code"""import osimport sysimport mathimport hashlibimport jsonimport shutilimport numpy as npdef generate_mesh_1d(x_min, x_max, x_tip, h_tip, h_outer, growth=1.12):    # 1. Left side from 0.0 to x_min (-0.5)    left_coords = [0.0]    curr_x = 0.0    curr_h = h_tip    while curr_x > x_min:        if curr_x > -0.04:            curr_h = h_tip        else:            curr_h = min(h_outer, curr_h * growth)        curr_x -= curr_h        if curr_x <= x_min + 0.25 * curr_h:            left_coords.append(x_min)            break        else:            left_coords.append(curr_x)    left_coords.reverse()        # 2. Right side from 0.0 to x_max (+0.5)    right_coords = []    curr_x = 0.0    curr_h = h_tip    while curr_x < x_max:        if curr_x < 0.15:            curr_h = h_tip        else:            curr_h = min(h_outer, curr_h * growth)        curr_x += curr_h        if curr_x >= x_max - 0.25 * curr_h:            right_coords.append(x_max)            break        else:            right_coords.append(curr_x)                all_coords = np.concatenate([left_coords, right_coords])    all_coords = np.unique(np.sort(all_coords))    all_coords[0] = x_min    all_coords[-1] = x_max    z_idx = np.argmin(np.abs(all_coords))    all_coords[z_idx] = 0.0    return all_coordsdef generate_stage_e_mesh(name, h_tip, h_outer, out_dir):    os.makedirs(out_dir, exist_ok=True)        x_coords = generate_mesh_1d(-0.5, 0.5, 0.0, h_tip, h_outer, growth=1.12)    y_half = generate_mesh_1d(0.0, 0.5, 0.0, h_tip, h_outer, growth=1.12)    y_coords = np.unique(np.sort(np.concatenate([-y_half[::-1], y_half])))        y_zero_idx = np.argmin(np.abs(y_coords))    y_coords[y_zero_idx] = 0.0    x_zero_idx = np.argmin(np.abs(x_coords))    x_coords[x_zero_idx] = 0.0        Nx = len(x_coords) - 1    Ny = len(y_coords) - 1    Ny_half = y_zero_idx        nodes = {} # nid -> (x, y)    elements = {} # eid -> [n1, n2, n3, n4]        # 1. Build bottom nodes (y <= 0)    bot_grid = np.zeros((Ny_half + 1, Nx + 1), dtype=int)    nid = 1    for j in range(Ny_half + 1):        y = y_coords[j]        for i in range(Nx + 1):            x = x_coords[i]            nodes[nid] = (x, y)            bot_grid[j, i] = nid            nid += 1                # 2. Build top nodes (y >= 0)    top_grid = np.zeros((Ny - Ny_half + 1, Nx + 1), dtype=int)    for j in range(Ny - Ny_half + 1):        y = y_coords[Ny_half + j]        for i in range(Nx + 1):            x = x_coords[i]            if j == 0:                if x > 0.0:                    # Ahead of crack tip: shared with bottom top-line                    top_grid[j, i] = bot_grid[Ny_half, i]                else:                    # Slit line x <= 0.0: independent duplicated node                    nodes[nid] = (x, y)                    top_grid[j, i] = nid                    nid += 1            else:                nodes[nid] = (x, y)                top_grid[j, i] = nid                nid += 1                    # 3. Build Physical Quads    eid = 1    # Bottom half elements    for j in range(Ny_half):        for i in range(Nx):            n1 = bot_grid[j, i]            n2 = bot_grid[j, i + 1]            n3 = bot_grid[j + 1, i + 1]            n4 = bot_grid[j + 1, i]            elements[eid] = [n1, n2, n3, n4]            eid += 1                # Top half elements    for j in range(Ny - Ny_half):        for i in range(Nx):            n1 = top_grid[j, i]            n2 = top_grid[j, i + 1]            n3 = top_grid[j + 1, i + 1]            n4 = top_grid[j + 1, i]            elements[eid] = [n1, n2, n3, n4]            eid += 1                num_nodes = len(nodes)    num_elements = len(elements)        # Quality metrics    h_x = np.diff(x_coords)    h_y = np.diff(y_coords)    min_h = min(np.min(h_x), np.min(h_y))    max_h = max(np.max(h_x), np.max(h_y))    l0 = 0.015        # Boundary Node Sets    top_nodes = []    bot_nodes = []    slit_top_nodes = []    slit_bot_nodes = []        for nid_k, (x, y) in nodes.items():        if abs(y - 0.5) < 1e-7:            top_nodes.append(nid_k)        if abs(y - (-0.5)) < 1e-7:            bot_nodes.append(nid_k)        if abs(y - 0.0) < 1e-7 and x <= 0.0:            if nid_k in top_grid[0, :]:                slit_top_nodes.append(nid_k)            if nid_k in bot_grid[Ny_half, :]:                slit_bot_nodes.append(nid_k)                    # Check positive Jacobians    for eid_k, conn in elements.items():        x1, y1 = nodes[conn[0]]        x2, y2 = nodes[conn[1]]        x3, y3 = nodes[conn[2]]        x4, y4 = nodes[conn[3]]        # 2D cross product of diagonals        det = (x3 - x1)*(y4 - y2) - (x4 - x2)*(y3 - y1)        if det <= 0.0:            raise ValueError("Non-positive element Jacobian in element %d: det=%.6e" % (eid_k, det))                # Write Corrected INP File matching 1390447 template    inp_path = os.path.join(out_dir, "%s.inp" % name)    with open(inp_path, "w", newline="\n") as fp:        fp.write("*HEADING\n")        fp.write("%s - Virgin Continuous Benchmark on Corrected Stage-E Mesh\n" % name)        fp.write("** Physical Nodes: %d, Physical Quads: %d\n" % (num_nodes, num_elements))        fp.write("** h_min: %.6f mm, h_max: %.6f mm, h_min/l0: %.4f\n" % (min_h, max_h, min_h / l0))        fp.write("**\n")                # User Element Header: Type U1 (Phase, DOF 3) and Type U2 (Mech, DOFs 1,2)        fp.write("*USER ELEMENT, TYPE=U1, NODES=4, COORDINATES=2, I PROPERTIES=0, PROPERTIES=7, VARIABLES=18, UNSYMM\n")        fp.write("3\n")        fp.write("*USER ELEMENT, TYPE=U2, NODES=4, COORDINATES=2, I PROPERTIES=0, PROPERTIES=7, VARIABLES=18, UNSYMM\n")        fp.write("1, 2\n")                # Nodes        fp.write("*NODE\n")        for nid_k, (x, y) in sorted(nodes.items()):            fp.write("%d, %.10f, %.10f\n" % (nid_k, x, y))        # Reference Point        fp.write("99999, 0.0, 0.500000\n")                # Layer 1: Phase field elements (E_QUAD_PHASE, 1 to N_phys)        fp.write("*ELEMENT, TYPE=U1, ELSET=E_QUAD_PHASE\n")        for eid_k, conn in sorted(elements.items()):            fp.write("%d, %d, %d, %d, %d\n" % (eid_k, conn[0], conn[1], conn[2], conn[3]))                    # Layer 2: Mechanical elements (E_QUAD_MECH, N_phys+1 to 2*N_phys)        fp.write("*ELEMENT, TYPE=U2, ELSET=E_QUAD_MECH\n")        for eid_k, conn in sorted(elements.items()):            fp.write("%d, %d, %d, %d, %d\n" % (eid_k + num_elements, conn[0], conn[1], conn[2], conn[3]))                    # Node Sets        fp.write("*NSET, NSET=N_BOTTOM\n")        for idx_k, n_k in enumerate(sorted(bot_nodes)):            fp.write("%d%s" % (n_k, ",\n" if (idx_k + 1) % 10 == 0 or idx_k == len(bot_nodes) - 1 else ", "))                    fp.write("*NSET, NSET=N_TOP\n")        for idx_k, n_k in enumerate(sorted(top_nodes)):            fp.write("%d%s" % (n_k, ",\n" if (idx_k + 1) % 10 == 0 or idx_k == len(top_nodes) - 1 else ", "))                    fp.write("*NSET, NSET=N_RP\n99999\n")                # UEL Properties: l0=0.015, Gc=0.0027, E=210.0, nu=0.3, k_tol=1e-7, N_PHYS, EXEC_MODE=0.0        fp.write("*UEL PROPERTY, ELSET=E_QUAD_PHASE\n")        fp.write("0.015, 0.0027, 210.0, 0.3, 1e-07, %d.0, 0.0\n" % num_elements)        fp.write("*UEL PROPERTY, ELSET=E_QUAD_MECH\n")        fp.write("0.015, 0.0027, 210.0, 0.3, 1e-07, %d.0, 0.0\n" % num_elements)                # Top Kinematic Coupling: Only Shear DOF 1 coupled to RP 99999        for n_k in sorted(top_nodes):            fp.write("*EQUATION\n2\n%d, 1, 1.0, 99999, 1, -1.0\n" % n_k)                    # Monotonic Step Definition matching 1390447        fp.write("** ==========================================================\n")        fp.write("** STEP 1: Continuous Monotonic Shear to U1 = 0.050 mm\n")        fp.write("** ==========================================================\n")        fp.write("*STEP, NAME=ShearStep, NLGEOM=NO, INC=10000\n")        fp.write("*STATIC\n")        fp.write("0.001, 1.0, 1.0e-9, 0.02\n")        fp.write("*BOUNDARY, OP=NEW\n")        fp.write("N_BOTTOM, 1, 2, 0.0\n")        fp.write("N_RP, 1, 1, 0.050000\n")        fp.write("N_RP, 2, 2, 0.0\n")        fp.write("*OUTPUT, FIELD, FREQ=1\n")        fp.write("*NODE OUTPUT\nU, RF\n")        fp.write("*NODE PRINT, FREQ=1\nU, RF\n")        fp.write("*EL PRINT, FREQ=1, ELSET=E_QUAD_MECH\nSDV14, SDV15, SDV16\n")        fp.write("*END STEP\n")            # Write Corrected PBS Launcher Script with Exit Code Propagation    pbs_path = os.path.join(out_dir, "submit_job.pbs")    with open(pbs_path, "w", newline="\n") as fp:        fp.write("#!/bin/bash\n")        fp.write("#PBS -N %s\n" % name[:15])        fp.write("#PBS -l select=1:ncpus=1:mem=16gb\n")        fp.write("#PBS -l walltime=24:00:00\n")        fp.write("#PBS -q entry_imfdfkmq\n")        fp.write("#PBS -m abe\n")        fp.write("#PBS -M pr21vyci@mailserver.tu-freiberg.de\n")        fp.write("#PBS -o pbs.out\n")        fp.write("#PBS -e pbs.err\n\n")        fp.write("cd $PBS_O_WORKDIR\n\n")        fp.write("module purge\n")        fp.write("module load gcc/11.4.0\n")        fp.write("module load intel/2024.2.0\n")        fp.write("module load abaqus/2023\n\n")        fp.write("echo \"Job started on $(hostname) at $(date)\"\n\n")        fp.write("abaqus job=%s input=%s.inp user=f44_mixed_uel_restart_stateinit.for cpus=1 interactive\n" % (name, name))        fp.write("ABAQUS_RC=$?\n\n")        fp.write("echo \"Abaqus finished with return code ${ABAQUS_RC} at $(date)\"\n\n")        fp.write("exit ${ABAQUS_RC}\n")            # Copy validated UEL subroutine    uel_src = "models/generated/mode_ii/production_state_transfer_batch/M2CORR_STAGE_D_CONTINUOUS_TARGET_CONTROL_VAL/f44_mixed_uel_restart_stateinit.for"    shutil.copy2(uel_src, os.path.join(out_dir, "f44_mixed_uel_restart_stateinit.for"))        # Compute manifest    manifest = {}    for f_k in sorted(os.listdir(out_dir)):        p_k = os.path.join(out_dir, f_k)        if os.path.isfile(p_k) and f_k != "manifest.json":            with open(p_k, "rb") as fp_k:                manifest[f_k] = hashlib.sha256(fp_k.read()).hexdigest()    with open(os.path.join(out_dir, "manifest.json"), "w", newline="\n") as fp_m:        json.dump(manifest, fp_m, indent=2)            metrics = {        "name": name,        "nodes": num_nodes,        "elements": num_elements,        "h_min_mm": float(min_h),        "h_max_mm": float(max_h),        "h_min_over_l0": float(min_h / l0),        "aspect_ratio_max": float(max(np.max(h_x)/np.min(h_y), np.max(h_y)/np.min(h_x))),        "num_split_nodes": len(slit_top_nodes)    }        print("Generated %s in %s" % (name, out_dir))    print("  Nodes: %d, Quads: %d (Phase: %d, Mech: %d), h_min: %.6f mm, h_max: %.6f mm, h_min/l0: %.4f" % (        num_nodes, num_elements, num_elements, num_elements, min_h, max_h, min_h / l0))    return metricsdef build_all_stage_e_meshes():    base_dir = "models/generated/mode_ii/stage_e_refinement_coarsening_batch"        # 1. Refined Target Continuous Baseline: h_tip = 0.002000 mm    ref_dir = os.path.join(base_dir, "M2CORR_STAGE_E_REFINED_TARGET_CONTINUOUS_VAL")    m_ref = generate_stage_e_mesh("M2CORR_STAGE_E_REFINED_TARGET_CONTINUOUS_VAL", 0.002000, 0.020000, ref_dir)        # 2. Coarsened Target Continuous Baseline: h_tip = 0.005000 mm    crs_dir = os.path.join(base_dir, "M2CORR_STAGE_E_COARSENED_TARGET_CONTINUOUS_VAL")    m_crs = generate_stage_e_mesh("M2CORR_STAGE_E_COARSENED_TARGET_CONTINUOUS_VAL", 0.005000, 0.030000, crs_dir)        summary_path = os.path.join(base_dir, "stage_e_mesh_metrics_summary.json")    with open(summary_path, "w", newline="\n") as fp:        json.dump({"refined_mesh": m_ref, "coarsened_mesh": m_crs}, fp, indent=2)    print("\nSaved Stage-E mesh metrics to %s" % summary_path)if __name__ == "__main__":    build_all_stage_e_meshes()